INSERT INTO service_categories (id, name, tagline, description, icon, image, tint, enabled, popular, commission_rate, inspection_fee, sort_order) VALUES
  ('ac-repair', 'AC Repair', 'Service, gas refill & installation', 'Certified AC technicians for split & window units — deep servicing, gas top-up, installation and diagnostics with a 30-day warranty.', 'snow-outline', 'https://images.unsplash.com/photo-1762341123870-d706f257a12e?auto=format&fit=crop&w=900&q=75', '#E8F4FF', true, true, 0.2, NULL, 0),
  ('electrician', 'Electrician', 'Wiring, switches, fans & lights', 'From a tripping MCB to complete rewiring — background-verified electricians with tools and spares.', 'flash-outline', 'https://images.unsplash.com/photo-1621905251189-08b45d6a269e?auto=format&fit=crop&w=900&q=75', '#FFF7E0', true, true, 0.18, NULL, 1),
  ('plumber', 'Plumbing', 'Leaks, taps, blockages & fittings', 'Skilled plumbers for leaks, clogged drains, bathroom fittings and tank connections.', 'water-outline', 'https://images.unsplash.com/photo-1749532125405-70950966b0e5?auto=format&fit=crop&w=900&q=75', '#E6F7F8', true, true, 0.18, NULL, 2),
  ('house-cleaning', 'House Cleaning', 'Deep cleaning for every room', 'Trained cleaning professionals with mechanised equipment and eco-friendly chemicals.', 'sparkles-outline', 'https://images.unsplash.com/photo-1740657254989-42fe9c3b8cce?auto=format&fit=crop&w=900&q=75', '#EAF8EE', true, true, 0.22, NULL, 3),
  ('painting', 'Painting', 'Walls, textures & waterproofing', 'Professional painters with premium brands, furniture covering and on-time completion.', 'color-palette-outline', 'https://images.unsplash.com/photo-1688372199140-cade7ae820fe?auto=format&fit=crop&w=900&q=75', '#FFEDEF', true, false, 0.15, NULL, 4),
  ('carpenter', 'Carpenter', 'Furniture repair & assembly', 'Expert carpenters for assembly, door and hinge repairs, shelves and modular fittings.', 'hammer-outline', 'https://images.unsplash.com/photo-1595844730298-b960ff98fee0?auto=format&fit=crop&w=900&q=75', '#F7EFE6', true, false, 0.18, NULL, 5),
  ('pest-control', 'Pest Control', 'Cockroach, termite & bed bugs', 'Odourless treatments safe for kids and pets, with a free follow-up visit.', 'bug-outline', 'https://images.unsplash.com/photo-1747659629851-a92bd71149f6?auto=format&fit=crop&w=900&q=75', '#EEF3E3', true, false, 0.2, NULL, 6),
  ('appliance-repair', 'Appliance Repair', 'Washing machine, fridge & more', 'Brand-trained technicians for washing machines, refrigerators, microwaves, RO purifiers and TVs.', 'hardware-chip-outline', 'https://images.unsplash.com/photo-1604335399105-a0c585fd81a1?auto=format&fit=crop&w=900&q=75', '#EEF0FF', true, false, 0.2, NULL, 7);
